contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test exercises C.fallback by sending an arbitrary amount and then asserts
    // the general invariant described in property_summary.
    function run(uint amount, uint beforeTimestamp, uint beforeBlockNumber) public payable {
        // we only allow sending exactly 10 ether to exercise the non-reverting path
        // require we have the funds to forward
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        // read observable state before the call
        uint pastBefore = c.pastBlockTime();
        uint balBefore = address(c).balance;

        // make the call to fallback: must be a top-level statement
        bool reverted;
        // We expect the call may revert if block.timestamp <= pastBefore or amount != 10 ether,
        // but we call with amount == 10 ether so revert only possible due to timestamp.
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable state after the call
        uint pastAfter = c.pastBlockTime();
        uint balAfter = address(c).balance;
        uint myBalAfter = address(this).balance;

        // Build the general rule asserted below:
        // If the call reverted, then nothing in c changed: pastBlockTime and balance unchanged.
        // If the call succeeded:
        //   - pastBlockTime equals block.timestamp (i.e., strictly greater than pastBefore)
        //   - If block.number % 15 == 0 then c forwarded its entire balance to this contract, so balAfter == 0 and myBalAfter >= balBefore + amount - (0) .
        //   - Otherwise balAfter == balBefore + amount.

        // We cannot use block.timestamp or block.number directly inside the assert for a general proof
        // because they are not parameters. Instead we express the rule using only observable values
        // and the known relation that success implies pastAfter > pastBefore.

        // The assert encodes:
        // reverted => (pastAfter == pastBefore && balAfter == balBefore)
        // !reverted => (pastAfter > pastBefore && (balAfter == balBefore + amount || balAfter == 0))
        assert(
            (reverted && pastAfter == pastBefore && balAfter == balBefore)
            || (
                !reverted
                && pastAfter > pastBefore
                && (balAfter == balBefore + amount || balAfter == 0)
            )
        );
    }

    // allow receiving Ether when C transfers out
    receive() external payable {}
}

