        uint pastBefore = c.pastBlockTime();
        uint balBefore = address(c).balance;

        // Make the call to C's fallback by address-call with value. Must be a top-level statement.
        bool reverted;
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        // Observe state after the call
        uint pastAfter = c.pastBlockTime();
