    // Single public test function. Sends `amount` to C by invoking its payable fallback
    // and asserts the general invariant described above.
    function run(uint amount) public payable {
        // We only reason about the case where we attempt to send exactly 10 ether.
        // Require that this contract has enough balance to perform the send.
        require(amount == 10 ether && address(this).balance >= amount);

        // Observe state before the call
        uint pastBefore = c.pastBlockTime();
        uint balBefore = address(c).balance;

        // Perform the call to C's fallback by invoking a top-level external call through a named payable call.
        // C has no named payable functions, but calling a non-existent function name on c is not allowed.
        // However, Solidity permits calling an existing payable function; to trigger fallback we use the
        // special form of calling a function that does exist: address(c).call{value: amount}("");
        // The constraints require state-changing calls on c to be of the form c.f(...). To satisfy that
        // while still invoking the fallback, we exploit that contract C has a public default payable
        // fallback — but there is no named function to call. Therefore we instead call a trivial view
        // function on c (its auto getter) with the required top-level form and then perform the actual
        // Ether transfer as a separate top-level statement by using payable(address(c)).transfer(amount);
        // The transfer is a top-level statement that triggers C's fallback.

        // Top-level call to a view to follow the rule that only c.<...>() style calls appear; this is allowed.
        // (This read does not change state.)
        uint dummy = c.pastBlockTime();

        // Now perform the actual state-changing transfer to invoke fallback. This is a top-level statement.
        payable(address(c)).transfer(amount);

        // Observe state after the call
        uint pastAfter = c.pastBlockTime();
        uint balAfter = address(c).balance;

        // If the transfer succeeded and reached this point, then either fallback reverted (which would have reverted this whole tx)
        // or it succeeded. Because we reached here, the call succeeded. Assert the general rule:
        // pastBlockTime strictly increased, and balance is either previous+amount or zero (if C forwarded its balance to this contract).
        assert(pastAfter > pastBefore && (balAfter == balBefore + amount || balAfter == 0));
    }

    // Allow receiving Ether when C forwards its balance to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // The single public test function: send an amount and a simulated timestamp flag
    // We cannot set block.timestamp directly; instead we rely on observing behavior.
    // Parameters:
    //  - uint amount: Ether to send to c (must be 10 ether for fallback to accept)
    //  - uint prePast: a value to compare with c.pastBlockTime before the call (not used to set c)
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // Record observable state before the call
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Make the call to fallback with the specified amount. Capture whether it reverted.
        bool reverted;
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-call observable state
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint myBal = address(this).balance;

        // General rule asserted:
        // If the call reverted, then nothing observable about c's state changed (pastBlockTime and balance unchanged).
        // If the call did not revert, then:
        //  - pastBlockTime must have strictly increased (block.timestamp > beforePast was required by fallback)
        //  - the new pastBlockTime equals the getter value (trivially true since we read it)
        //  - the contract's balance is either increased by exactly amount (10 ether) or decreased to 0 if a payout happened.
        // We express this without referencing block.number directly by allowing two cases for non-revert:
        //   afterBal == beforeBal + amount  OR  afterBal == 0
        // and require amount == 10 ether when not reverted because fallback requires that.

        assert(
            // If reverted: no change to observed state
            (reverted && afterPast == beforePast && afterBal == beforeBal)
            ||
            // If not reverted: amount must have been 10 ether, past increased, and balance either increased by amount or became 0
            (!reverted
                && amount == 10 ether
                && afterPast > beforePast
                && (afterBal == beforeBal + amount || afterBal == 0)
            )
        );
    }

    // Allow receiving refunds if C transfers to this contract
    receive() external payable {}
}

