contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // receive to accept potential refunds/transfers from C
    receive() external payable {}

    // single public test function driven by inputs
    function run(uint sendAmount, uint callTimestamp, uint callBlockNumber) public payable {
        // We can't set block.timestamp or block.number; those are environment variables.
        // But we must supply an amount to forward. Ensure the test contract has enough balance.
        require(address(this).balance >= sendAmount, "insufficient balance for test");

        // Read observable pre-state
        uint beforePast = c.pastBlockTime();
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // perform the call to fallback with the supplied amount and capture revert
        bool reverted = false;
        // Must call c.fallback by sending to address(c). Note: using low-level call to trigger fallback.
        (bool ok, ) = address(c).call{value: sendAmount}("");
        if (!ok) {
            reverted = true;
        }

        // Read observable post-state
        uint afterPast = c.pastBlockTime();
        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        /* General rule asserted:
           If the call reverted, then state must be unchanged (pastBlockTime and balances equal).
           If the call did not revert and sendAmount == 10 ether then:
             - afterPast > beforePast (fallback requires block.timestamp > pastBlockTime)
             - either C did not pay out: afterCBalance == beforeCBalance + sendAmount and this balance decreased by sendAmount,
               or C did pay out on that call: afterCBalance == 0 and this contract's balance increased by beforeCBalance (minus gas),
               but since gas is external, we assert the expected balance relation using only observable balances:
                 if payout occurred then afterCBalance == 0 and afterThisBalance >= beforeThisBalance - sendAmount + beforeCBalance
           If the call did not revert and sendAmount != 10 ether then fallback would revert, so this branch shouldn't occur.
        */

        assert(
            // if reverted: nothing changed
            (reverted && afterPast == beforePast && afterCBalance == beforeCBalance && afterThisBalance == beforeThisBalance)
            ||
            // if not reverted: then sendAmount must equal 10 ether and time advanced
            (!reverted && sendAmount == 10 ether && afterPast > beforePast && (
                // Either payout happened: contract balance becomes 0 and this contract's balance increased at least by prior c balance minus the sent amount
                (afterCBalance == 0 && afterThisBalance >= beforeThisBalance - sendAmount + beforeCBalance)
                ||
                // Or no payout: contract keeps the sent amount, this contract lost the sent amount
                (afterCBalance == beforeCBalance + sendAmount && afterThisBalance == beforeThisBalance - sendAmount)
            ))
        );
    }
 }

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // accept potential refunds/transfers from C
    receive() external payable {}

    // Single public test function driven by inputs.
    // We send `amount` wei to C by calling its fallback via the typed external call c.fallback{value: amount}().
    // To satisfy the requirement that state-changing calls on c must be top-level, we call c.fallback directly.
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // observe pre-state
        uint beforePast = c.pastBlockTime();
        uint beforeCBalance = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform the call to C's fallback and record whether it reverted
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-state
        uint afterPast = c.pastBlockTime();
        uint afterCBalance = address(c).balance;
        uint afterThis = address(this).balance;

        // General invariant asserted for all inputs:
        // - If the call reverted then nothing observable changed.
        // - If it did not revert then amount must have been exactly 10 ether, and block.timestamp must have been > beforePast (so afterPast > beforePast).
        //   Additionally, after a successful call the contract either retained the sent 10 ether (balance increased by amount)
        //   or it paid out its entire balance (afterCBalance == 0 and this contract's balance reflects receiving that payout).
        assert(
            (reverted && afterPast == beforePast && afterCBalance == beforeCBalance && afterThis == beforeThis)
            ||
            (!reverted && amount == 10 ether && afterPast > beforePast && (
                // retained the sent amount
                (afterCBalance == beforeCBalance + amount && afterThis == beforeThis - amount)
                ||
                // paid out entire balance: contract balance becomes 0 and this address's balance is at least beforeThis - amount + beforeCBalance
                (afterCBalance == 0 && afterThis >= beforeThis - amount + beforeCBalance)
            ))
        );
    }
}

