contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to accept Ether so this contract can send to c
    receive() external payable {}

    // Single public test function with inputs: amount to send and a chosen timestamp/trigger isn't possible to set,
    // but we can observe behavior via return values and balances.
    function run(uint amount) public payable {
        // Ensure this contract has enough balance to send the requested amount to c
        require(address(this).balance >= amount);

        // Read pre-call observable state
        uint prePast = c.pastBlockTime();
        uint preBalanceC = address(c).balance;
        uint preBalanceThis = address(this).balance;

        bool reverted;
        // Make the state-changing call to c via fallback by sending Ether
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-call observable state
        uint postPast = c.pastBlockTime();
        uint postBalanceC = address(c).balance;
        uint postBalanceThis = address(this).balance;

        // General rule covering all cases:
        // - If call reverted, then pastBlockTime and balances unchanged.
        // - If call did not revert and amount != 10 ether then this shouldn't happen (fallback requires 10),
        //   but to be general: when not reverted and amount == 10 ether:
        //     * postPast >= prePast (since fallback sets pastBlockTime = block.timestamp only when it proceeds)
        //     * if block.timestamp <= prePast then call must have reverted (so non-revert implies block.timestamp > prePast)
        //     * If block.number % 15 == 0 then c paid out entire balance to caller so postBalanceC == 0 and
        //       postBalanceThis == preBalanceThis - amount + preBalanceC + amount == preBalanceThis + preBalanceC
        //     * Otherwise c did not send funds out, so postBalanceC == preBalanceC + amount and postBalanceThis == preBalanceThis - amount
        // We encode these as a single assert capturing the implications using only observable values and the revert flag.

        // Compute boolean for block-number payout possibility via the observable relation between balances.
        // Since we cannot read block.number here, we deduce payout case by balance change patterns.

        // Build the comprehensive condition
        bool condReverted = reverted && postPast == prePast && postBalanceC == preBalanceC && postBalanceThis == preBalanceThis;

        // Non-reverted path: amount must be exactly 10 ether and block.timestamp > prePast and past updated to current timestamp
        bool nonRevertBasics = (!reverted) && (amount == 10 ether) && (postPast >= prePast) && (postPast != prePast);

        // Determine payout observed: payout happened if contract lost at least preBalanceC (i.e., postBalanceC == 0)
        bool observedPayout = (!reverted) && (postBalanceC == 0);

        // When payout observed: postBalanceThis should equal preBalanceThis - amount + preBalanceC + amount = preBalanceThis + preBalanceC
        bool payoutBalanceConsistent = observedPayout && (postBalanceThis == preBalanceThis + preBalanceC);

        // When no payout observed and not reverted: contract simply received the amount
        bool noPayoutBalanceConsistent = (!reverted) && (!observedPayout) && (postBalanceC == preBalanceC + amount) && (postBalanceThis == preBalanceThis - amount);

        // Combine all allowed scenarios
        assert(condReverted || (nonRevertBasics && (payoutBalanceConsistent || noPayoutBalanceConsistent)));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Accept Ether so this contract can send to c and possibly receive refund/payout
    receive() external payable {}

    function run(uint amount) public payable {
        // ensure this contract has the funds to send
        require(address(this).balance >= amount);

        // observe pre-state
        uint prePast = c.pastBlockTime();
        uint preBalanceC = address(c).balance;
        uint preBalanceThis = address(this).balance;

        bool reverted;
        // call fallback by sending Ether to c
        try c.call{value: amount}("") returns (bool ok, bytes memory) {
            // c.call returns (bool, bytes) as low-level; ok indicates low-level success
            reverted = !ok;
        } catch {
            reverted = true;
        }

        // observe post-state
        uint postPast = c.pastBlockTime();
        uint postBalanceC = address(c).balance;
        uint postBalanceThis = address(this).balance;

        // The general rule (single assert):
        // - If the call reverted then nothing observable changed.
        // - Otherwise (not reverted): the sent amount must be exactly 10 ether,
        //   pastBlockTime must have been updated to a strictly greater value,
        //   and either the contract performed a payout (contract balance becomes 0 and this contract's balance increases by preBalanceC)
        //   or no payout happened (contract balance increased by amount and this balance decreased by amount).
        assert(
            // reverted case: all observables unchanged
            (reverted && postPast == prePast && postBalanceC == preBalanceC && postBalanceThis == preBalanceThis)
            ||
            // non-reverted case: amount == 10 ether, past updated strictly, and balances follow one of two mutually exclusive patterns
            (
                (!reverted)
                && (amount == 10 ether)
                && (postPast > prePast)
                && (
                    // payout happened: contract lost its previous balance (now 0) and this contract gained that amount
                    (postBalanceC == 0 && postBalanceThis == preBalanceThis + preBalanceC - amount + amount) // simplifies to preBalanceThis + preBalanceC
                    ||
                    // no payout: contract simply received the amount
                    (postBalanceC == preBalanceC + amount && postBalanceThis == preBalanceThis - amount)
                )
            )
        );
    }
}

