                && afterPast == curTime
                && (
                    (curBlock % 15 == 0 && afterBal == 0)
                    || (curBlock % 15 != 0 && afterBal == beforeBal + sendAmount)
                )
            )
            : (sendAmount != 10 ether || curTime <= beforePast)
