contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry that performs the test
    function run(uint sendAmount, uint fakeBlockNumber, uint fakeTimestamp) public payable {
        // require enough balance in this test contract to send the requested amount
        require(address(this).balance >= sendAmount);

        // read observable before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // We cannot actually set block.number or block.timestamp; the contract uses them.
        // The property will observe behavior when the call succeeds vs reverts.

        bool reverted;
        // perform the call that may revert; must be top-level
        try c.f{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable after-values
        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;
        uint myBalance = address(this).balance;

        // General rule:
        // If the call reverted, then nothing about c's state is required here (the assert allows revert flag true).
        // If the call did NOT revert, then sendAmount must have been exactly 10 ether (per contract),
        // and c.pastBlockTime must have been updated to some non-decreasing timestamp (we assert it's >= beforePast),
        // and either the contract kept its funds (afterBalance == beforeBalance + sendAmount) or it paid out its entire balance to this contract
        // (which we detect by afterBalance == 0 and myBalance increased by beforeBalance + sendAmount).

        // To avoid relying on precise timestamp, assert monotonicity of pastBlockTime when a call succeeds,
        // and the conditional balance behavior described above.

        assert(
            reverted
            || (
                // successful call implies sendAmount was accepted by require(msg.value == 10 ether)
                sendAmount == 10 ether
                // pastBlockTime must not decrease
                && afterPast >= beforePast
                // balance either increased by sendAmount (no payout) or became zero (payout of entire balance)
                && (
                    afterBalance == beforeBalance + sendAmount
                    || (
                        afterBalance == 0
                        // when payout happens, this contract's balance must have increased by beforeBalance + sendAmount
                        && myBalance >= (beforeBalance + sendAmount)
                    )
                )
            )
        );
    }

    // allow receiving Ether when C.transfer sends funds to this test contract
    receive() external payable {}
}
